import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { TabBarProps } from "./tab-bar.types";
import type { CSSObject } from "@emotion/react";

import * as RadixTabs from "@radix-ui/react-tabs";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "TabBar";

// Generate child element class names for the component, should match available style slots
export const TabBarClasses = {
  root: "exp-textura_tab-bar",
  list: "exp-textura_tab-bar_list",
  listWrapper: "exp-textura_tab-bar_list_wrapper",
  panel: "exp-textura_tab-bar_panel",
  sm: "exp-textura_tab-bar_sm",
  menuTab: "exp-textura_tab-bar_menu_tab",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  line: {
    listWrapper: {
      borderBottom: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
    },
  },
});

const generateStyles = (props: TabBarProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<TabBarProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "block",
    width: "100%",
    backgroundColor: "unset",
    color: theme.tab.default.color.content.enabled,
    ...theme.typography.body.md,

    [`.${TabBarClasses.listWrapper}`]: {
      position: "relative",
      alignItems: "center",
      justifyContent: "center",
      display: "flex",
      ...styleSlots?.listWrapper,
    },

    [`.${TabBarClasses.list}`]: {
      textAlign: "center",
      alignItems: "center",
      display: "flex",
      gap: theme.toRem(theme.spacing[4]),
      justifyContent: "flex-start",
      width: "100%",
      ...styleSlots?.list,
    },

    [`&.${TabBarClasses.sm}`]: {
      ...theme.typography.body.sm,
      ...styleSlots?.sm,
    },

    [`.${TabBarClasses.panel}`]: {
      ...theme.typography.body.md,
      color: theme.color.content.default,
      cursor: "default",
      height: "inherit",
      backgroundClip: "content-box",
      outline: "none",
      borderRadius: `0 ${theme.toRem(theme.border.radius.sm)} ${theme.toRem(theme.border.radius.sm)} ${theme.toRem(theme.border.radius.sm)}`,
      "&:focus-visible": {
        ...styleSlots?.panelFocus,
      },
      "&[data-state='active']": {
        padding: `${theme.toRem(theme.spacing[8])} 0 0 0`,
        ...styleSlots?.panelActive,
      },
      ":dir(rtl)": {
        borderRadius: `${theme.toRem(theme.border.radius.sm)} 0 ${theme.toRem(theme.border.radius.sm)} ${theme.toRem(theme.border.radius.sm)}`,
      },
      ...styleSlots?.panel,
    },

    [`> .${TabBarClasses.menuTab}`]: {
      width: "100%",
      display: "flex",
      justifyContent: "space-between",
      padding: 0,
      color: "unset",
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledTabBar = styled(RadixTabs.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<TabBarProps>((props) => generateStyles(props));
